import numpy as np
def equation(eps, T, params):
    a,b,c,d,e,f,g,h,k,q = params[:10]
    s=np.sqrt(T)
    return (a+b*s+c*T**2) + (d+e*s+f*T**2)*eps + (g+h*s)*np.exp(-k*eps) + q*np.log(eps)
